import { describe, expect, it } from 'vitest';
import { multiply } from '../../src/math';

describe('multiply', () => {
  it('rounds the product to a whole number', () => {
    expect(multiply(2.5, 1.5)).toBe(4);
  });

  it('refuses a negative number', () => {
    expect(() => multiply(-2, 5)).toThrow(RangeError);
  });

  it('returns the product as text', () => {
    expect(multiply(3, 4)).toEqual('12');
  });
});
